{"content": "from typing import Dict, List

from pydantic import BaseModel, Field, ValidationError, field_validator


class CreateUser(BaseModel):
    username: str = Field(..., min_length=3)
    age: int

    @field_validator("username")
    @classmethod
    def no_spaces(cls, v: str) -> str:
        if " " in v:
            raise ValueError("username must not contain spaces")
        return v


# Map Pydantic's error messages to our stable public error codes.
# Pydantic v2 changed the message wording, so these prefixes are updated.
MESSAGE_CODES = {
    "Field required": "MISSING",
    "Input should be a valid integer": "NOT_AN_INTEGER",
    "String should have at least": "TOO_SHORT",
}


def error_codes(payload: dict) -> Dict[str, List[str]]:
    try:
        CreateUser(**payload)
    except ValidationError as exc:
        out: Dict[str, List[str]] = {}
        for err in exc.errors():
            code = next((c for m, c in MESSAGE_CODES.items() if err["msg"].startswith(m)), "INVALID")
            out.setdefault(str(err["loc"][0]), []).append(code)
        return out
    return {}
